"""Combine completed independent camera audits with exact case coverage."""
from pathlib import Path
import json,argparse,hashlib,numpy as np
ap=argparse.ArgumentParser();ap.add_argument('--split',choices=['heldout_view','train'],default='heldout_view');a=ap.parse_args();LAB=Path(__file__).resolve().parents[2];out=LAB/'outputs/dynamic-human-enerf-support-030';name='independent-image-audit' if a.split=='heldout_view' else 'independent-training-image-audit';m=json.loads((out/('evaluation' if a.split=='heldout_view' else 'training-evaluation')/'metrics.json').read_text());reports=[];receipts=[]
for c in m['cameras']:
    p=out/f'{name}-camera{c}.json';r=json.loads(p.read_text());assert r['cameras']==[c] and r['split']==a.split;reports.append(r);receipts.append(dict(file=p.name,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
checks=[c for r in reports for c in r['checks']];temporal=[t for r in reports for t in r['temporal']];expected={(c,t,g) for c in m['cameras'] for t in m['frames'] for g in m['models']};actual=[(r['camera'],r['frame'],r['model']) for r in checks];assert len(actual)==len(set(actual)) and set(actual)==expected
result=dict(status='all_camera_RGB_alpha_reference_region_and_temporal_audits_verified',split=a.split,cameras=m['cameras'],images=len(checks),alpha_images=sum(r['alpha_images'] for r in reports),references=sum(r['references'] for r in reports),person_regions=sum(r['person_regions'] for r in reports),temporal_transitions=len(temporal),max_ssim_implementation_difference=max(r['max_ssim_implementation_difference'] for r in reports),source_audits=receipts,checks=checks,temporal=temporal,temporal_summary={g:float(np.mean([r['mean_abs_change_residual'] for r in temporal if r['model']==g])) for g in m['models']} if temporal else {},methods=reports[0]['methods'],limits=reports[0]['limits'])
(out/f'{name}.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf8');print(json.dumps({k:v for k,v in result.items() if k not in ['checks','temporal','source_audits']},indent=2))
